EXPECTED_SHA256 = "3b7f0c9a1d2e4f5a6b7c8d9e0f1a2b3c4d5e6f708192a3b4c5d6e7f8091a2b3c"

def fetch_detector(dest: Path):
    data = requests.get("https://models.example.com/fake/detector.onnx", timeout=30).content
    if hashlib.sha256(data).hexdigest() != EXPECTED_SHA256:
        raise ValueError("checksum mismatch")
    dest.write_bytes(data)
    return ort.InferenceSession(str(dest))

